#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=3

banner "Локальная установка Ollama для RAG"

ollama_runtime_path() {
  local ollama_bin ollama_prefix
  ollama_bin=$(readlink -f "$(command -v ollama)")
  ollama_prefix=$(dirname "$(dirname "$ollama_bin")")
  printf '%s/lib/ollama/llama-server\n' "$ollama_prefix"
}

stage "Проверка компьютера"
say "Проверим GPU, свободное место и уже установленную версию Ollama."
if ! nvidia-smi >/dev/null 2>&1; then
  warn "nvidia-smi не видит GPU. Ollama сможет работать на CPU, но медленнее."
else
  nvidia-smi --query-gpu=name,memory.total,driver_version --format=csv,noheader
fi
available_kb=$(df -Pk . | awk 'NR==2 {print $4}')
if (( available_kb < 12582912 )); then
  warn "Свободно меньше 12 ГБ. Освободите место перед загрузкой моделей."
  exit 1
fi
if command -v ollama >/dev/null 2>&1; then
  OLLAMA_RUNTIME=$(ollama_runtime_path)
  if [[ -x "$OLLAMA_RUNTIME" ]]; then
    say "Ollama установлен полностью: $(ollama --version 2>/dev/null || true)"
  else
    warn "Найдена только команда Ollama, но отсутствует runtime: $OLLAMA_RUNTIME"
    warn "На следующем шаге мастер восстановит неполную установку."
  fi
else
  say "Ollama пока не установлен. На следующем шаге понадобится пароль sudo."
fi
pause "Проверка завершена. Нажмите Enter."

stage "Установка Ollama"
if command -v ollama >/dev/null 2>&1; then
  OLLAMA_RUNTIME=$(ollama_runtime_path)
  if [[ -x "$OLLAMA_RUNTIME" ]]; then
    say "Пропускаем установку: команда и runtime Ollama доступны."
    NEED_OLLAMA_INSTALL=0
  else
    warn "Установка неполная: отсутствует $OLLAMA_RUNTIME"
    NEED_OLLAMA_INSTALL=1
  fi
else
  NEED_OLLAMA_INSTALL=1
fi
if (( NEED_OLLAMA_INSTALL )); then
  say "Будет выполнен официальный установщик https://ollama.com/install.sh."
  say "Пароль вводится непосредственно в sudo и нигде не сохраняется."
  if confirm "Установить или восстановить Ollama системно?"; then
    curl -fsSL https://ollama.com/install.sh | sh
  else
    warn "Установка отменена. Мастер остановлен без изменений."
    exit 1
  fi
fi
if ! command -v ollama >/dev/null 2>&1; then
  warn "После установки команда ollama не найдена в PATH."
  exit 1
fi
OLLAMA_RUNTIME=$(ollama_runtime_path)
if [[ ! -x "$OLLAMA_RUNTIME" ]]; then
  warn "Установка не завершена: отсутствует $OLLAMA_RUNTIME"
  warn "Повторите запуск при стабильном соединении с интернетом."
  exit 1
fi
ollama --version
if curl -fsS --connect-timeout 2 http://127.0.0.1:11434/api/version >/dev/null 2>&1; then
  say "Локальный API Ollama уже запущен."
elif command -v systemctl >/dev/null 2>&1 \
  && systemctl list-unit-files --type=service 2>/dev/null | grep -q '^ollama.service'; then
  say "Запускаем установленную systemd-службу Ollama."
  sudo systemctl start ollama
else
  say "Служба ollama.service отсутствует; запускаем пользовательский сервер."
  mkdir -p "$HOME/.ollama"
  nohup ollama serve >"$HOME/.ollama/ollama.log" 2>&1 &
  echo $! >"$HOME/.ollama/ollama.pid"
fi
for _attempt in {1..30}; do
  if curl -fsS --connect-timeout 2 http://127.0.0.1:11434/api/version >/dev/null 2>&1; then
    break
  fi
  sleep 1
done
if ! curl -fsS --connect-timeout 2 http://127.0.0.1:11434/api/version >/dev/null 2>&1; then
  warn "Ollama не запустился. Проверьте журнал $HOME/.ollama/ollama.log"
  exit 1
fi

# The official systemd service runs as user "ollama" and therefore uses a
# different model store than an older user-launched server. Reuse already
# downloaded models instead of downloading the same 6.4 GB again.
USER_MODELS="$HOME/.ollama/models"
SYSTEM_MODELS="/usr/share/ollama/.ollama/models"
if command -v systemctl >/dev/null 2>&1 \
  && systemctl is-active --quiet ollama.service 2>/dev/null \
  && ! ollama list 2>/dev/null | grep -q '^qwen3:8b' \
  && [[ -f "$USER_MODELS/manifests/registry.ollama.ai/library/qwen3/8b" ]] \
  && [[ -f "$USER_MODELS/manifests/registry.ollama.ai/library/bge-m3/latest" ]]; then
  warn "Служба Ollama не видит уже загруженные модели из $USER_MODELS."
  say "Их можно перенести в системное хранилище без повторной загрузки."
  if confirm "Перенести qwen3:8b и bge-m3 в хранилище службы Ollama?"; then
    MIGRATION_STAMP=$(date +%Y%m%d-%H%M%S)
    sudo systemctl stop ollama
    sudo install -d -o ollama -g ollama "$(dirname "$SYSTEM_MODELS")"
    if sudo test -e "$SYSTEM_MODELS"; then
      SYSTEM_MODELS_BACKUP="${SYSTEM_MODELS}.before-migration-${MIGRATION_STAMP}"
      sudo mv "$SYSTEM_MODELS" "$SYSTEM_MODELS_BACKUP"
      say "Предыдущий системный каталог сохранён: $SYSTEM_MODELS_BACKUP"
    fi
    sudo mv "$USER_MODELS" "$SYSTEM_MODELS"
    sudo chown -R ollama:ollama "$SYSTEM_MODELS"
    sudo systemctl start ollama
    for _attempt in {1..30}; do
      if curl -fsS --connect-timeout 2 http://127.0.0.1:11434/api/version >/dev/null 2>&1; then
        break
      fi
      sleep 1
    done
    say "Готовые модели перенесены в системное хранилище Ollama."
  else
    note "Миграция пропущена; модели будут загружены заново на следующем шаге."
  fi
fi
pause "Ollama установлен и запущен. Нажмите Enter."

stage "Модели и проверка GPU"
say "Скачаем qwen3:8b для ответов и bge-m3 для embeddings (около 6,4 ГБ)."
ollama pull qwen3:8b
ollama pull bge-m3
say "Проверяем генерацию короткого ответа."
ollama run qwen3:8b "Ответь одним словом без рассуждений: готов"
say "Проверяем локальный endpoint embeddings."
curl -fsS http://127.0.0.1:11434/api/embed \
  -H 'Content-Type: application/json' \
  -d '{"model":"bge-m3","input":"проверка локального поиска"}' \
  | grep -q 'embeddings'
say "Загруженные модели:"
ollama list
say "Активные модели и распределение по CPU/GPU:"
ollama ps || true

finish
